insert into public.organizations (id, name, slug, timezone, currency, tagline, contact_phone, contact_email, deposit_percent, payment_instructions, check_in_instructions, cancellation_policy) values
  ('f4c24128-d88e-4a62-a49d-eb3c497bc69d', 'Sunrise Villas & Suites', 'sunrise', 'Asia/Manila', 'PHP', 'Beachfront stays in Siargao', '+63 917 800 1234', 'reservations@sunrisevillas.example', 50, 'Pay via GCash 0917 800 1234 (Sunrise Villas Inc.) or BDO Savings 0012-3456-7890. Send your proof of payment and booking reference to our reservations team.', 'Check-in is from 2:00 PM and check-out is by 11:00 AM. Please bring a valid government ID. Our front desk at the beach entrance is open 7 AM – 10 PM; message us if you will arrive later.', 'Free cancellation up to 7 days before check-in. Within 7 days the deposit is non-refundable. No-shows are charged the full stay.'),
  ('9f881307-c796-4ac4-a4bc-2a5a2119edae', 'Island Wheels Rentals', 'island-wheels', 'Asia/Manila', 'PHP', 'Vans, SUVs and scooters for island trips', '+63 928 700 4455', 'rent@islandwheels.example', 30, 'Pay the deposit via GCash 0928 700 4455 (Island Wheels). Balance is collected in cash on pickup together with a ₱5,000 refundable security deposit.', 'Pickup is at the Depot from 8:00 AM. Bring your driver’s license and one valid ID. Return the vehicle with the same fuel level.', 'Free cancellation up to 48 hours before pickup. After that the deposit is forfeited.');
