  ('20bbd425-d48f-4d15-ae7f-e964acbe26ea', 'f4c24128-d88e-4a62-a49d-eb3c497bc69d', 'c39f8455-3174-405d-ac6c-f8c3556268bb', '39199a57-1d4d-4181-a34e-11042a112778', 'in', 'Hi, we booked Ocean View for the 24th. Can you arrange an airport pick-up for 4 adults?', '2026-10-03T04:15:00.000Z', '2026-10-03T04:40:00.000Z', null),
