  ('8458c60a-3e8c-45bd-ac2c-136a654f5d62', 'f4c24128-d88e-4a62-a49d-eb3c497bc69d', 'booking_confirmation', 'Booking confirmation', 'Hi {{guest}}, your booking {{ref}} at {{business}} is CONFIRMED! {{property}} · {{checkIn}} → {{checkOut}} ({{nights}} nights) · Total {{total}}. We can’t wait to host you. Questions? Call {{phone}}.'),
  ('6dd6703f-d122-484f-a1d3-5d3e167f8cb8', 'f4c24128-d88e-4a62-a49d-eb3c497bc69d', 'check_in', 'Check-in instructions', 'Hi {{guest}}, we’re ready for your arrival on {{checkIn}}! Check-in starts at 2:00 PM. Please message us when you’re 30 minutes away and bring a valid ID. Booking ref: {{ref}}.'),
